window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8b1846cf99bf3cfd"]={"versions": [{"id": "FIG-8b1846cf99bf3cfd", "releases": ["R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Konzeptionelles Testarchitektur- und Schichtenmodell für Konformitäts- und Abnahmetests (angelehnt an das ISO/IEC 9646 Conformance Testing Framework).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR ATS RTE (<em>Acceptance Test Suite for Runtime Environment</em>), Release R1.1.0.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des standardisierten Testaufbaus für <strong>Intra-ECU-Tests</strong>. Fokus ist die isolierte funktionale Verifikation der generierten RTE und deren Inter-SWC-Kommunikationsmechanismen (Sender-Receiver, Client-Server, Mode-Switch, Inter-Runnable Variables) auf einem einzelnen Steuergerät ohne Einbindung des externen Kommunikationsstacks (Com, PduR, Bus-Treiber).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Test System (Host):</strong></li>\n<li>Externe Teststeuerungs- und Ausführungseinheit (z. B. TTCN-3-Host, PC-basierte Testautomatisierung).</li>\n<li>Verwaltet Testsuiten, steuert Testabläufe, generiert Stimuli und evaluiert Testergebnisse (Verdicts: Pass/Fail).</li>\n<li><strong>SUT (System Under Test):</strong></li>\n<li>Das reale Zielsteuergerät (Target-ECU), bestehend aus Hardware und Software-Schichten:</li>\n<li><strong>Microcontroller:</strong> Ziel-Hardwareplattform (MCU/Core).</li>\n<li><strong>Basic Software (BSW):</strong> Zugrundeliegender AUTOSAR-Basissoftware-Stack (insbesondere das AUTOSAR OS zur Bereitstellung von Tasks, Events, Ressourcen und Alarmen für die RTE).</li>\n<li><strong>Runtimeenvironment (RTE):</strong> Die generierte VFB-Abstraktionsschicht und eigentliche Zielkomponente der Verifikation.</li>\n<li><strong>Control SWC (Upper Tester):</strong> Applikative Testkomponente im SUT. Dient als aktiver Stimulator (Sender/Client), der RTE-Schnittstellen anregt.</li>\n<li><strong>Observation SWC (Upper Tester):</strong> Applikative Testkomponente im SUT. Dient als passiver Monitor/Senke (Receiver/Server), der RTE-Ausgaben und Callbacks erfasst.</li>\n<li><strong>PCO (Points of Control and Observation):</strong></li>\n<li>Formal definierte Schnittstellenpunkte gemäß ISO 9646.</li>\n<li>Liegen exakt an den VFB-konformen Schnittstellen zwischen Applikations-SWCs und der RTE (z. B. Funktionsaufrufe <code>Rte_Write_<em></code>, <code>Rte_Read_</em></code>, <code>Rte_Call_<em></code>, <code>Rte_Result_</em></code>).</li>\n<li><strong>Test Coordination Procedures (TCP):</strong></li>\n<li>Standardisierter Kommunikationspfad und Synchronisationsprotokoll zwischen dem externen Test System und den Upper Testern (Control SWC / Observation SWC) auf dem Target (z. B. via CAN/Ethernet-Diagnosekanal, XCP, serieller Link oder Debugger-Mailbox).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Test-Initialisierung & Parametrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Test System konfiguriert die Control SWC und Observation SWC über die <em>Test Coordination Procedures</em> (TCP) für den anstehenden Testfall (Erwartungswerte, Puffergrößen, Trigger-Modi).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Stimulation (Control Path via PCO 1):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Test System stößt per TCP die <code>Control SWC</code> an.</li>\n<li>Die <code>Control SWC</code> ruft deterministisch die zu testende RTE-API am PCO auf (z. B. synchrones Senden via <code>Rte_Write</code>, Queued Sender-Receiver, Client-Server-Request <code>Rte_Call</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Intra-ECU RTE-Verarbeitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die RTE verarbeitet das Datum/Event vollständig lokal: Pufferung, implizites/explizites Daten-Handling, Routing, OS-Task-Aktivierung oder Event-Dispatching (<code>Rte_Event</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Observation & Monitoring (Observation Path via PCO 2):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die RTE leitet das Datum an die <code>Observation SWC</code> weiter (Ausführung einer Runnable-Entity, Empfang via <code>Rte_Read</code>, Bereitstellung von Server-Rückgabewerten).</li>\n<li>Die <code>Observation SWC</code> erfasst Empfangsdaten, Timestamps, OS-Zustände sowie API-Rückgabewerte (<code>Std_ReturnType</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ergebnisübertragung & Verdict:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die protokollierten Messwerte werden über TCP an das Test System zurückgesendet.</li>\n<li>Das Test System vollzieht den Soll-Ist-Abgleich und bestimmt das Testergebnis.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-Vertrags- und Generierungsvalidierung:</strong></li>\n<li>Der Aufbau dient dem Nachweis, dass der RTE-Generator (<code>Generation Phase</code>) den semantischen Vertrag der VFB-Modelle (Ports, Interfaces, Data Types, ComSpecs) für rein interne Kommunikation fehlerfrei in Target-Code übersetzt hat.</li>\n<li><strong>Nicht-invasive PCO-Nutzung:</strong></li>\n<li>Upper Tester (SWCs) dürfen das Laufzeitverhalten der RTE nicht instrumentieren oder verfälschen; der Zugriff hat zwingend über standardisierte <code>Rte_Ports</code> und Application Data Types zu erfolgen.</li>\n<li><strong>Vermeidung von BSW-Seiteneffekten:</strong></li>\n<li>Für Intra-ECU-Tests werden Kommunikationsmodule wie <code>Com</code> oder <code>PduR</code> nicht durchlaufen. Treten Fehler im Testlauf auf, sind diese isoliert auf fehlerhafte RTE-Generierung, OS-Konfiguration (Task-Mapping, Prioritäten-Inversion, Event-Zuordnung) oder Speicherzugriffsverletzungen zurückzuführen.</li>\n<li><strong>Einfluss der Test Coordination Procedures (TCP):</strong></li>\n<li>Die Bandbreite und CPU-Last des TCP-Treibers dürfen die zyklischen Tasks der RTE nicht verdrängen. Für zeitkritische Tests müssen Stimulationsdaten vorab gepuffert und Ergebnisse post-mortem übertragen werden.</li>\n</ul>"}, {"id": "FIG-e5798e77c7105ddc", "releases": ["R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Konzeptionelles Testarchitektur- und Schichtenmodell für Konformitäts- und Abnahmetests (angelehnt an das ISO/IEC 9646 Conformance Testing Framework).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR ATS RTE (<em>Acceptance Test Suite for Runtime Environment</em>), Release R1.1.0.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des standardisierten Testaufbaus für <strong>Intra-ECU-Tests</strong>. Fokus ist die isolierte funktionale Verifikation der generierten RTE und deren Inter-SWC-Kommunikationsmechanismen (Sender-Receiver, Client-Server, Mode-Switch, Inter-Runnable Variables) auf einem einzelnen Steuergerät ohne Einbindung des externen Kommunikationsstacks (Com, PduR, Bus-Treiber).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Test System (Host):</strong></li>\n<li>Externe Teststeuerungs- und Ausführungseinheit (z. B. TTCN-3-Host, PC-basierte Testautomatisierung).</li>\n<li>Verwaltet Testsuiten, steuert Testabläufe, generiert Stimuli und evaluiert Testergebnisse (Verdicts: Pass/Fail).</li>\n<li><strong>SUT (System Under Test):</strong></li>\n<li>Das reale Zielsteuergerät (Target-ECU), bestehend aus Hardware und Software-Schichten:</li>\n<li><strong>Microcontroller:</strong> Ziel-Hardwareplattform (MCU/Core).</li>\n<li><strong>Basic Software (BSW):</strong> Zugrundeliegender AUTOSAR-Basissoftware-Stack (insbesondere das AUTOSAR OS zur Bereitstellung von Tasks, Events, Ressourcen und Alarmen für die RTE).</li>\n<li><strong>Runtimeenvironment (RTE):</strong> Die generierte VFB-Abstraktionsschicht und eigentliche Zielkomponente der Verifikation.</li>\n<li><strong>Control SWC (Upper Tester):</strong> Applikative Testkomponente im SUT. Dient als aktiver Stimulator (Sender/Client), der RTE-Schnittstellen anregt.</li>\n<li><strong>Observation SWC (Upper Tester):</strong> Applikative Testkomponente im SUT. Dient als passiver Monitor/Senke (Receiver/Server), der RTE-Ausgaben und Callbacks erfasst.</li>\n<li><strong>PCO (Points of Control and Observation):</strong></li>\n<li>Formal definierte Schnittstellenpunkte gemäß ISO 9646.</li>\n<li>Liegen exakt an den VFB-konformen Schnittstellen zwischen Applikations-SWCs und der RTE (z. B. Funktionsaufrufe <code>Rte_Write_<em></code>, <code>Rte_Read_</em></code>, <code>Rte_Call_<em></code>, <code>Rte_Result_</em></code>).</li>\n<li><strong>Test Coordination Procedures (TCP):</strong></li>\n<li>Standardisierter Kommunikationspfad und Synchronisationsprotokoll zwischen dem externen Test System und den Upper Testern (Control SWC / Observation SWC) auf dem Target (z. B. via CAN/Ethernet-Diagnosekanal, XCP, serieller Link oder Debugger-Mailbox).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Test-Initialisierung & Parametrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Test System konfiguriert die Control SWC und Observation SWC über die <em>Test Coordination Procedures</em> (TCP) für den anstehenden Testfall (Erwartungswerte, Puffergrößen, Trigger-Modi).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Stimulation (Control Path via PCO 1):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das Test System stößt per TCP die <code>Control SWC</code> an.</li>\n<li>Die <code>Control SWC</code> ruft deterministisch die zu testende RTE-API am PCO auf (z. B. synchrones Senden via <code>Rte_Write</code>, Queued Sender-Receiver, Client-Server-Request <code>Rte_Call</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Intra-ECU RTE-Verarbeitung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die RTE verarbeitet das Datum/Event vollständig lokal: Pufferung, implizites/explizites Daten-Handling, Routing, OS-Task-Aktivierung oder Event-Dispatching (<code>Rte_Event</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Observation & Monitoring (Observation Path via PCO 2):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die RTE leitet das Datum an die <code>Observation SWC</code> weiter (Ausführung einer Runnable-Entity, Empfang via <code>Rte_Read</code>, Bereitstellung von Server-Rückgabewerten).</li>\n<li>Die <code>Observation SWC</code> erfasst Empfangsdaten, Timestamps, OS-Zustände sowie API-Rückgabewerte (<code>Std_ReturnType</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ergebnisübertragung & Verdict:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die protokollierten Messwerte werden über TCP an das Test System zurückgesendet.</li>\n<li>Das Test System vollzieht den Soll-Ist-Abgleich und bestimmt das Testergebnis.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-Vertrags- und Generierungsvalidierung:</strong></li>\n<li>Der Aufbau dient dem Nachweis, dass der RTE-Generator (<code>Generation Phase</code>) den semantischen Vertrag der VFB-Modelle (Ports, Interfaces, Data Types, ComSpecs) für rein interne Kommunikation fehlerfrei in Target-Code übersetzt hat.</li>\n<li><strong>Nicht-invasive PCO-Nutzung:</strong></li>\n<li>Upper Tester (SWCs) dürfen das Laufzeitverhalten der RTE nicht instrumentieren oder verfälschen; der Zugriff hat zwingend über standardisierte <code>Rte_Ports</code> und Application Data Types zu erfolgen.</li>\n<li><strong>Vermeidung von BSW-Seiteneffekten:</strong></li>\n<li>Für Intra-ECU-Tests werden Kommunikationsmodule wie <code>Com</code> oder <code>PduR</code> nicht durchlaufen. Treten Fehler im Testlauf auf, sind diese isoliert auf fehlerhafte RTE-Generierung, OS-Konfiguration (Task-Mapping, Prioritäten-Inversion, Event-Zuordnung) oder Speicherzugriffsverletzungen zurückzuführen.</li>\n<li><strong>Einfluss der Test Coordination Procedures (TCP):</strong></li>\n<li>Die Bandbreite und CPU-Last des TCP-Treibers dürfen die zyklischen Tasks der RTE nicht verdrängen. Für zeitkritische Tests müssen Stimulationsdaten vorab gepuffert und Ergebnisse post-mortem übertragen werden.</li>\n</ul>"}], "trans": [{"from": "FIG-8b1846cf99bf3cfd", "to": "FIG-e5798e77c7105ddc", "fr": "R1.1.0", "tr": "R1.2.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
